def prefix_suffix_common(s: str) -> int:
    # Initialize pointers for both ends of the string
    left, right = 0, len(s) - 1

    # Loop until the two pointers meet or cross
    while left < right:
        # If characters at both pointers match, move both pointers inward
        if s[left] == s[right]:
            left += 1
            right -= 1
        else:
            # If characters do not match, return the length of the common prefix found so far
            return left

    # If all characters match, return the full length of the string
    return len(s)
