def longest_bitonic_length(nums: list[int]) -> int:
    n = len(nums)
    if n == 0:
        return 0

    # Initialize left and right arrays to store the length of increasing and decreasing subsequences respectively
    left = [1] * n
    right = [1] * n

    # Compute the length of increasing subsequences from left to right
    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                left[i] = max(left[i], left[j] + 1)

    # Compute the length of decreasing subsequences from right to left
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if nums[i] > nums[j]:
                right[i] = max(right[i], right[j] + 1)

    # The maximum length of bitonic subsequence is the sum of the maximum lengths of increasing and decreasing subsequences at each index
    max_length = 0
    for i in range(n):
        max_length = max(max_length, left[i] + right[i] - 1)

    return max_length
