from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    def is_valid(x, y):
        return 0 <= x < rows and 0 <= y < cols

    def bfs(start):
        queue = deque([(start, 0)])
        visited = set()

        while queue:
            x, y, steps = queue.popleft()

            if grid[x][y] == 'E':
                return steps

            for dx, dy in directions:
                nx, ny = x + dx, y + dy

                if is_valid(nx, ny) and (nx, ny) not in visited and grid[nx][ny] != '#':
                    visited.add((nx, ny))
                    queue.append((nx, ny, steps + 1))

        return -1

    start = None
    end = None

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if start is None or end is None:
        raise ValueError("Start or end point not found")

    return bfs(start)
