def boustrophedon_order(matrix: list[list[int]]) -> list[int]:
    result = []
    rows, cols = len(matrix), len(matrix[0])

    # Initialize pointers for traversal
    row, col = 0, cols - 1

    while row < rows and col >= 0:
        if row == 0 or col == cols - 1:
            # Add elements from the current column to the result
            for i in range(row, rows):
                result.append(matrix[i][col])
        else:
            # Add elements from the current row to the result
            for i in range(col, -1, -1):
                result.append(matrix[row][i])

        # Move pointers to the next position
        row += 1
        col -= 1

    return result
