from collections import OrderedDict

def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    cache = OrderedDict()
    hits = []
    misses = []

    for operation in operations:
        key, value = operation
        if key in cache:
            hits.append(key)
            cache.move_to_end(key)  # Move the accessed item to the end of the cache
        else:
            misses.append(key)
            if len(cache) == capacity:
                cache.popitem(last=False)  # Remove the least recently used item
            cache[key] = value

    return hits, misses

