from typing import List

def min_coins_bounded(coins: List[int], limits: List[int], target: int) -> int:
    # Initialize a list to store the minimum coins needed for each amount up to target
    dp = [float('inf')] * (target + 1)
    dp[0] = 0  # Base case: 0 coins needed for 0 amount

    # Iterate through each coin and its limit
    for coin, limit in zip(coins, limits):
        # Update the dp array for amounts from coin to target
        for i in range(coin, target + 1):
            if i - coin <= limit:
                dp[i] = min(dp[i], dp[i - coin] + 1)

    return dp[target] if dp[target] != float('inf') else -1

