from collections import defaultdict

def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    def bfs(start):
        queue = [(start, 0)]
        visited = set()
        while queue:
            node, distance = queue.pop(0)
            if node == target:
                return distance
            if node not in visited:
                visited.add(node)
                for neighbor in graph[node]:
                    queue.append((neighbor, distance + 1))
        return float('inf')

    shortest_path = bfs(source)
    if shortest_path == float('inf'):
        return 0

    # Count paths of length k
    def dfs(node, path_length):
        nonlocal count
        if path_length == shortest_path:
            count += 1
            return
        for neighbor in graph[node]:
            dfs(neighbor, path_length + 1)

    count = 0
    dfs(source, 0)
    return count
