def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    for instruction in program:
        if instruction.startswith('PUSH'):
            value = int(instruction.split()[1])
            stack.append(value)
        elif instruction == 'POP':
            if stack:
                stack.pop()
            else:
                raise ValueError("Stack underflow")
        elif instruction == 'ADD':
            if len(stack) < 2:
                raise ValueError("Insufficient operands for ADD")
            b, a = stack.pop(), stack.pop()
            stack.append(a + b)
        elif instruction == 'SUB':
            if len(stack) < 2:
                raise ValueError("Insufficient operands for SUB")
            b, a = stack.pop(), stack.pop()
            stack.append(a - b)
        elif instruction == 'MUL':
            if len(stack) < 2:
                raise ValueError("Insufficient operands for MUL")
            b, a = stack.pop(), stack.pop()
            stack.append(a * b)
        elif instruction == 'DIV':
            if len(stack) < 2:
                raise ValueError("Insufficient operands for DIV")
            b, a = stack.pop(), stack.pop()
            if b == 0:
                raise ValueError("Division by zero")
            stack.append(int(a / b))
        elif instruction == 'PRINT':
            print(stack[-1])
        else:
            raise ValueError(f"Unknown instruction: {instruction}")
    return stack
