from typing import List, Tuple

def free_slots(busy: List[Tuple[int, int]], day_start: int, day_end: int, min_len: int) -> List[Tuple[int, int]]:
    free = []
    for start, end in busy:
        if start < day_start or end > day_end:
            continue
        if len(free) == 0 or free[-1][1] + 1 < start:
            free.append((start, end))
        else:
            free[-1][1] = max(free[-1][1], end)
    return [slot for slot in free if slot[1] - slot[0] >= min_len]
