def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    rows, cols = len(grid), len(grid[0])
    new_grid = [[0] * cols for _ in range(rows)]

    # Iterate over each cell in the grid
    for i in range(rows):
        for j in range(cols):
            # Calculate the number of sand grains at the current cell
            sand_grains = sum(grid[x][y] for x in range(max(0, i-1), min(rows, i+2)) 
                                for y in range(max(0, j-1), min(cols, j+2)))

            # If the cell has more than 3 sand grains, it will topple
            if sand_grains > 3:
                # Distribute the excess sand grains to its neighbors
                for dx in [-1, 0, 1]:
                    for dy in [-1, 0, 1]:
                        if dx == 0 and dy == 0:
                            continue
                        nx, ny = i + dx, j + dy
                        if 0 <= nx < rows and 0 <= ny < cols:
                            new_grid[nx][ny] += sand_grains // 4
                            if sand_grains % 4 != 0:
                                new_grid[i][j] -= 1

    return new_grid
