                # Distribute the excess sand grains to its neighbors
                for dx in [-1, 0, 1]:
                    for dy in [-1, 0, 1]:
                        if dx == 0 and dy == 0:
                            continue
                        nx, ny = i + dx, j + dy
                        if 0 <= nx < rows and 0 <= ny < cols:
                            new_grid[nx][ny] += sand_grains // 4
                            if sand_grains % 4 != 0:
                                new_grid[i][j] -= 1

    return new_grid

