def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    cache = []
    hit_count = 0
    miss_count = 0

    for operation in operations:
        key, value = operation
        if key in cache:
            cache.remove(key)
            cache.append(key)
            hit_count += 1
        else:
            if len(cache) == capacity:
                cache.pop(0)
            cache.append(key)
            miss_count += 1

    return cache, [hit_count, miss_count]

