def compute_lcm(a: int, b: int) -> int:
    if a == 0 or b == 0:
        return 0

    # Calculate the greatest common divisor (GCD)
    def gcd(x, y):
        while y != 0:
            x, y = y, x % y
        return x

    # Compute LCM using the formula: lcm(a, b) = abs(a*b) // gcd(a, b)
    return abs(a * b) // gcd(a, b)
