def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    while True:
        # Count the number of grains in each cell
        counts = [[0] * len(row) for row in grid]
        for i in range(len(grid)):
            for j in range(len(grid[i])):
                counts[i][j] = sum(grid[x][y] for x, y in [(i-1, j), (i+1, j), (i, j-1), (i, j+1)] if 0 <= x < len(grid) and 0 <= y < len(grid[0]))

        # Check if any cell has more than three grains
        if all(count <= 3 for row in counts for count in row):
            break

        # Perform toppling operation
        for i in range(len(grid)):
            for j in range(len(grid[i])):
                if counts[i][j] > 3:
                    grid[i][j] -= 4
                    if i > 0:
                        grid[i-1][j] += 1
                    if i < len(grid)-1:
                        grid[i+1][j] += 1
                    if j > 0:
                        grid[i][j-1] += 1
                    if j < len(grid[0])-1:
                        grid[i][j+1] += 1

    return grid
