import zipfile

def unzip_member_text(zip_path: str, member: str) -> str:
    try:
        with zipfile.ZipFile(zip_path, 'r') as zip_ref:
            # Check if the member exists in the ZIP file
            if member in zip_ref.namelist():
                # Extract the member from the ZIP file
                extracted_data = zip_ref.read(member)
                # Decode the extracted data from bytes to a string using UTF-8 encoding
                decoded_string = extracted_data.decode('utf-8')
                return decoded_string
            else:
                raise KeyError(f"Member '{member}' not found in the ZIP file.")
    except FileNotFoundError:
        raise FileNotFoundError(f"The ZIP file '{zip_path}' was not found.")
    except Exception as e:
        raise Exception(f"An error occurred while processing the ZIP file: {e}")
