def boustrophedon_order(matrix: list[list[int]]) -> list[int]:
    if not matrix:
        return []

    result = []
    rows, cols = len(matrix), len(matrix[0])
    direction = 1  # 1 for down, -1 for up

    i, j = 0, 0
    while i < rows and j < cols:
        result.append(matrix[i][j])

        if direction == 1:
            if j + 1 < cols:
                j += 1
            else:
                i += 1
                direction = -1
        else:
            if i + 1 < rows:
                i += 1
            else:
                j -= 1
                direction = 1

    return result
