def balanced_ternary_str(n: int) -> str:
    if n == 0:
        return '0'

    result = []
    while n != 0:
        remainder = n % 3
        if remainder == -1:
            result.append('-')
            n += 3
        else:
            result.append(str(remainder))
            n //= 3

    # Reverse the list to get the correct order
    result.reverse()
    return ''.join(result)
