def balanced_ternary_str(n: int) -> str:
    if n == 0:
        return "0"

    result = ""
    sign = ""

    while n != 0:
        remainder = n % 3
        if remainder == -1:
            result += "-"
            sign = "-"
        else:
            result += "+" if remainder == 1 else "0"

        n //= 3

    # Ensure the first non-zero digit appears at the beginning
    if sign == "-":
        result = "-" + result[1:]

    return result[::-1]
