import hashlib

def derive_key(passphrase: str, salt: bytes) -> bytes:
    # Concatenate the passphrase and salt
    combined = passphrase.encode('utf-8') + salt

    # Use SHA-256 hashing to generate the key
    return hashlib.sha256(combined).digest()

