    """
    Converts a 2D list (matrix) into a dictionary with tuples as keys and integers as values.

    Parameters:
    - matrix: A 2D list of integers.

    Returns:
    - A dictionary where each key is a tuple (row index, column index) of a non-zero element,
      and each value is the integer at that position in the matrix.

    If all elements in the matrix are zero, returns an empty dictionary.
    """
    result = {}
    for i, row in enumerate(matrix):
        for j, value in enumerate(row):
            if value != 0:
                result[(i, j)] = value
    return result

