    # Initialize the cache as an empty dictionary and the access order list as an empty list
    cache = {}
    access_order = []

    # Process each operation in the list
    for op_type, key in operations:
        if op_type == 'get':
            # If the key exists in the cache, update its position in the access order
            if key in cache:
                access_order.remove(key)
                access_order.append(key)
            else:
                # If the key does not exist, add it to the cache with a default value (None)
                cache[key] = None
        elif op_type == 'put':
