            else:
                # If the cache is full, remove the least recently used item from the cache
                if len(cache) >= capacity:
                    lru_key = access_order.pop(0)
                    del cache[lru_key]
                # Add the new key-value pair to the cache
                cache[key] = value

    # Return the final state of the cache and the order of access
    return list(cache.items()), access_order
