        for i in range(col):
            result.append(matrix[row-1][i])
            row -= 1

        if row == 0:
            break

        for i in range(1, col):
            result.append(matrix[row-1][col-i-1])
            row -= 1

        if row == 0:
            break

        direction *= -1

    return result
