def shortest_path_one_break(grid: list[str]) -> int:
    rows = len(grid)
    cols = len(grid[0])

    # Find the starting point (S) and ending point (E)
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    # Directions for moving up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Initialize a queue with the starting point and distance 0
    queue = [(start, 0)]
    visited = set()

    while queue:
        current, dist = queue.pop(0)

        # Check if we have reached the end
        if current == end:
            return dist

        # Mark the current cell as visited
        visited.add(current)

        # Explore all four possible directions
        for dx, dy in directions:
            new_x, new_y = current[0] + dx, current[1] + dy

            # Check if the new position is within bounds and not a wall
            if 0 <= new_x < rows and 0 <= new_y < cols and grid[new_x][new_y] != '#':
                # Add the new position to the queue with incremented distance
                queue.append(((new_x, new_y), dist + 1))

    # If no path is found, return -1
    return -1
