def solve_congruences(congruences: List[Tuple[int, int]]) -> Tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    # Initialize variables for the extended Euclidean algorithm
    x, y = 1, 0
    s, t = 0, 1

    # Iterate through each congruence
    for r, m in reversed(congruences):
        q = x // m
        x, y = y, x - q * y
        s, t = t, s - q * t

    # Adjust the solution to satisfy all congruences
    x %= sum(m for _, m in congruences)

    # Check if the solution satisfies all congruences
    if any(x != r % m for r, m in congruences):
        return None

    return (x, len(congruences))
