import re

def parse_kv_pairs(text: str) -> dict[str, str]:
    if not text:
        return {}

    # Split the text into individual key-value pairs using semicolon as the delimiter
    pairs = text.split(';')

    # Initialize an empty dictionary to store the parsed key-value pairs
    result = {}

    for pair in pairs:
        # Use regular expression to match key-value pairs
        match = re.match(r'(\S+)\s*=\s*(.*)', pair)
        if match:
            key, value = match.groups()
            # Strip leading and trailing whitespace from both key and value
            result[key.strip()] = value.strip()

    return result
