def balanced_ternary_str(n: int) -> str:
    if n == 0:
        return '0'

    # Convert negative number to positive
    if n < 0:
        n = -n

    result = ''
    while n > 0:
        remainder = n % 3
        if remainder == 2:
            result = '-' + result
            n -= 4
        else:
            result = str(remainder) + result
            n //= 3

    return result
