from datetime import datetime, timedelta

def add_business_days(start: str, n: int, holidays: list[str]) -> str:
    # Convert start date string to datetime object
    start_date = datetime.strptime(start, "%Y-%m-%d")

    # Initialize the result date with the start date
    result_date = start_date

    # Adjust for holidays
    while n > 0:
        result_date += timedelta(days=1)
        if result_date.strftime("%Y-%m-%d") not in holidays:
            n -= 1

    # Format the result date back to a string
