def is_allowed_webhook(url: str) -> bool:
    # Regular expression pattern for validating the URL
    pattern = r'^https:\/\/[a-zA-Z0-9.-]+\.[a-zA-Z]{2,}(:\d+)?$'

    # Check if the URL matches the pattern
    if re.match(pattern, url):
        # Split the URL into components
        scheme, netloc, path, query, fragment = url.split('/')

        # Check if the hostname contains reserved words
        if 'localhost' in netloc or '.localhost' in netloc:
            return False

        # Check if the port is 443
        if ':' in netloc:
            port = int(netloc.split(':')[1])
            if port != 443:
                return False

        return True
    else:
        return False

