from typing import List, Tuple

def count_shortest_paths(n: int, edges: List[Tuple[int, int]], source: int, target: int) -> int:
    # Initialize a dictionary to store the distance from the source to each node
    distances = {node: float('inf') for node in range(1, n + 1)}
    distances[source] = 0

    # Create a priority queue to process nodes with the smallest distance first
    import heapq
    pq = [(0, source)]

    while pq:
        current_distance, current_node = heapq.heappop(pq)

        # If we have reached the target node, return the distance
        if current_node == target:
            return current_distance

        # Explore all neighbors of the current node
        for neighbor, weight in edges:
            if neighbor != current_node and current_distance + weight < distances[neighbor]:
                distances[neighbor] = current_distance + weight
                heapq.heappush(pq, (distances[neighbor], neighbor))

    # If no path exists, return 0
    return 0

