import re

def is_allowed_webhook(url: str) -> bool:
    # Regular expression to match the URL pattern
    url_pattern = r'^https://[a-zA-Z0-9.-]+(\.[a-zA-Z0-9.-]+)?(:[80|443])?$'

    # Check if the URL matches the pattern
    if re.match(url_pattern, url):
        # Split the URL into components
        parts = url.split('.')

        # Check if there are more than two labels
        if len(parts) > 2:
            return False

        # Check if the last label does not end with a dot
        if parts[-1].endswith('.'):
            return False

        # Check if the host part contains only valid characters
        for part in parts[:-1]:
            if not re.match(r'[a-zA-Z0-9.-]+$', part):
                return False

        # Check if the port number is either 80 or 443
        if parts[-1] == '80' or parts[-1] == '443':
            return True

    return False

