import re

def fetch_target_allowed(url: str, allowed_hosts: list[str]) -> bool:
    # Check if the URL starts with http or https
    if not url.startswith(('http://', 'https://')):
        return False

    # Extract the host from the URL
    host = url.split('//')[1].split('/')[0]

    # Remove the port number if present
    if ':' in host:
        host = host[:host.index(':')]

    # Check for '@' symbol in the host
    if '@' in host:
        return False

    # Check if the host ends with a '.' unless it is followed by another dot
    if host.endswith('.') and not host.endswith('..'):
        return False

    # Split the allowed hosts into domains and ports
    allowed_domains = [re.sub(r':\d+', '', host) for host in allowed_hosts]

    # Check if the host matches any of the allowed domains
    if host not in allowed_domains:
        return False

    # Check if the port number is present in the allowed hosts
    for allowed_host in allowed_hosts:
        if host in allowed_host:
            return True

    return False

import re

def fetch_target_allowed(url: str, allowed_hosts: list[str]) -> bool:
    # Regular expression to match the URL pattern
    url_pattern = r'^https?://([^@]+)\.(?:[^.]|$)'

    # Check if the URL matches the pattern
    if not re.match(url_pattern, url):
        return False

    # Extract the host from the URL
    host = re.search(r'([^@]+)', url).group(1)

    # Split the host into domain and port parts
    domain_parts = host.split('.')

    # Check if the domain part matches any of the allowed domains
    for allowed_host in allowed_hosts:
        allowed_domain_parts = allowed_host.split('.')

        # Check if the domain parts match exactly
        if len(domain_parts) != len(allowed_domain_parts):
            continue

        match = True
        for i in range(len(domain_parts)):
            if domain_parts[i] != allowed_domain_parts[i]:
                match = False
                break

        if match:
            # Check if the port number is present in the allowed hosts
            if ':' in allowed_host:
                allowed_port = int(re.search(r':(\d+)$', allowed_host).group(1))
                if url.endswith(f':{allowed_port}'):
                    return True
            else:
                return True

    return False

