    if exp == 0:
        return [[1] * len(matrix[0]) for _ in range(len(matrix))]
    elif exp == 1:
        return matrix

    # Base case for small exponents
    if exp < 4:
        result = [[0] * len(matrix[0]) for _ in range(len(matrix))]
        for i in range(len(matrix)):
            for j in range(len(matrix[0])):
                result[i][j] = matrix[i][j]
