def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    def can_overflow(x, y):
        return grid[x][y] >= 4

    def distribute_grains(x, y):
        if can_overflow(x, y):
            grid[x][y] -= 4
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]):
                    grid[nx][ny] += 1

    while True:
        changed = False
        for i in range(len(grid)):
            for j in range(len(grid[i])):
                if can_overflow(i, j):
                    distribute_grains(i, j)
                    changed = True
        if not changed:
            break
    return grid
