import math

def rolling_variance(nums: list[float], k: int) -> list[float]:
    if k <= 0 or k > len(nums):
        return []

    variances = []
    for i in range(len(nums)):
        if i < k:
            mean = sum(nums[:i+1]) / (i + 1)
            squared_diffs = [(x - mean) ** 2 for x in nums[:i+1]]
            variance = sum(squared_diffs) / (i + 1)
        else:
            mean = sum(nums[i-k+1:i+1]) / k
            squared_diffs = [(x - mean) ** 2 for x in nums[i-k+1:i+1]]
            variance = sum(squared_diffs) / k

        variances.append(round(variance, 3))

    return variances

