def matrix_power_mod(matrix: list[list[int]], exp: int, mod: int) -> list[list[int]]:
    if exp == 0:
        return [[1] * len(matrix[0]) for _ in range(len(matrix))]

    half_exp = exp // 2
    half_matrix = matrix_power_mod(matrix, half_exp, mod)

    result = [[sum(a*b % mod for a, b in zip(row, col)) % mod for col in half_matrix] for row in half_matrix]

    if exp % 2 != 0:
        result = [[sum(a*b % mod for a, b in zip(row, col)) % mod for col in matrix] for row in result]

    return result

