def is_public_ip(ip_str: str) -> bool:
    try:
        # Check for IPv4 addresses
        if re.match(r'^(\d{1,3}\.){3}\d{1,3}$', ip_str):
            parts = ip_str.split('.')
            for part in parts:
                if int(part) < 0 or int(part) > 255:
                    return False
            return True

        # Check for IPv6 addresses
        elif re.match(r'^([0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}$', ip_str):
            return True

        # Check for mixed format (IPv4 with optional IPv6)
        elif re.match(r'^(?:\d{1,3}\.){3}\d{1,3}(:[0-9a-fA-F]{1,4})?$', ip_str):
            parts = ip_str.split(':')
            if len(parts) == 1:
                return is_public_ip(parts[0])
            else:
                return is_public_ip(parts[0]) and is_public_ip(parts[1])

        # If none of the above matches, return False
        return False
    except ValueError:
        return False
