def league_table(results: List[Tuple[str, str, int, int]]) -> List[Tuple[str, int, int, int]]:
    if not results:
        return []

    # Calculate points for each team
    team_points = {}
    for home_team, away_team, home_goals, away_goals in results:
        if home_team in team_points:
            team_points[home_team] += 3 * (home_goals > away_goals) + (home_goals == away_goals)
        else:
            team_points[home_team] = 3 * (home_goals > away_goals)

        if away_team in team_points:
            team_points[away_team] += 3 * (away_goals > home_goals) + (away_goals == home_goals)
        else:
            team_points[away_team] = 3 * (away_goals > home_goals)

    # Sort teams by points, goal difference, and goals scored
    sorted_teams = sorted(team_points.items(), key=lambda x: (-x[1], -abs(x[0][0] - x[0][1]), -int(x[0][2]), -int(x[0][3])))

    # Format the result as a list of tuples
    formatted_result = [(team, points, abs(home_goals - away_goals), int(home_goals)) for team, points in sorted_teams]

    return formatted_result
