    if not source.strip():
        return []

    tokens = []
    for match in re.finditer(r'\b\d+\b|\b[a-zA-Z_]+\b|[=!<>+-*/.,()]\b', source):
        tokens.append((match.group(0).strip(), match.group(0)))

    if len(tokens) == 1 and tokens[0][0] == '':
        raise ValueError("Input string contains only whitespace.")

    return tokens
