def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    for instruction in program:
        parts = instruction.split()
        if len(parts) != 2:
            return None
        op, arg = parts[0], int(parts[1])
        if op == 'PUSH':
            stack.append(arg)
        elif op == 'POP':
            if not stack:
                return None
            stack.pop()
        elif op == 'DUP':
            if not stack:
                return None
            stack.append(stack[-1])
        elif op == 'SWAP':
            if len(stack) < 2:
                return None
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif op == 'ADD':
            if len(stack) < 2:
                return None
            stack[-2] += stack[-1]
            stack.pop()
        elif op == 'SUB':
            if len(stack) < 2:
                return None
            stack[-2] -= stack[-1]
            stack.pop()
        elif op == 'MUL':
            if len(stack) < 2:
                return None
            stack[-2] *= stack[-1]
            stack.pop()
        else:
            return None
        if len(stack) > 1000:
            return None
    return stack
