def balanced_ternary_str(n: int) -> str:
    if n == 0:
        return "0"

    digits = []
    while n > 0:
        digits.append(str(n % 3))
        n //= 3

    # Reverse the list of digits
    digits.reverse()

    # Ensure the result has at least 4 characters by adding leading zeros
    while len(digits) < 4:
        digits.insert(0, '0')

    # Join the digits together to form the balanced ternary string
    return ''.join(digits)
