def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    ip = 0

    while ip < len(program):
        instruction = program[ip]

        if instruction == "PUSH":
            value = int(program[ip + 1])
            stack.append(value)
            ip += 2
        elif instruction == "POP":
            if not stack:
                raise ValueError("Stack underflow")
            stack.pop()
            ip += 1
        elif instruction == "DUP":
            if not stack:
                raise ValueError("Stack underflow")
            stack.append(stack[-1])
            ip += 1
        elif instruction == "SWAP":
            if len(stack) < 2:
                raise ValueError("Not enough elements in stack")
            stack[-1], stack[-2] = stack[-2], stack[-1]
            ip += 1
        elif instruction == "ADD":
            if len(stack) < 2:
                raise ValueError("Not enough elements in stack")
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b)
            ip += 1
        elif instruction == "SUB":
            if len(stack) < 2:
                raise ValueError("Not enough elements in stack")
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
            ip += 1
        elif instruction == "MUL":
            if len(stack) < 2:
                raise ValueError("Not enough elements in stack")
            b = stack.pop()
            a = stack.pop()
            stack.append(a * b)
            ip += 1
        elif instruction == "JUMP":
            target = int(instruction[5:])
            ip = target - 1
        elif instruction == "JEZ":
            if stack[-1] == 0:
                target = int(instruction[4:])
                ip = target - 1
            else:
                ip += 1
        elif instruction == "HALT":
            break
        else:
            raise ValueError(f"Unknown instruction: {instruction}")

    return stack
