def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    # Determine the maximum length of each column
    max_lengths = [max(len(cell) for cell in col) for col in zip(*rows)]

    # Format each row
    formatted_rows = []
    for row in rows:
        formatted_row = []
        for i, cell in enumerate(row):
            padding = " " * (max_lengths[i] - len(cell))
            if aligns[i] == 'l':
                formatted_row.append(f"{padding}{cell}")
            elif aligns[i] == 'r':
                formatted_row.append(f"{cell}{padding}")
            else:
                formatted_row.append(f"{cell:{aligns[i]}}")
        formatted_rows.append(" | ".join(formatted_row))

    # Join all formatted rows into a single string
    return "\n".join(formatted_rows)
