import re

def is_local_redirect(target: str, host: str) -> bool:
    # Regular expression pattern to match a local redirect
    pattern = r'^[hH][tT][tP|pS]:\/\/[^/]+\/.*$'

    # Check if the target matches the pattern
    if re.match(pattern, target):
        # Extract the host from the target
        extracted_host = re.search(r'//([^/]+)', target).group(1)

        # Compare the extracted host with the given host
        return extracted_host.lower() == host.lower()
    else:
        return False

