from collections import deque

def min_slides(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    start, end = None, None

    # Find the starting and ending positions
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if start is None or end is None:
        return -1  # No valid starting or ending position

    queue = deque([(start, 0)])
    visited = set()

    while queue:
        x, y, moves = queue.popleft()

        if (x, y) == end:
            return moves

        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx, ny = x + dx, y + dy

            if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] != '#' and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny, moves + 1))

    return -1  # Exit cell cannot be reached
```

This solution uses a breadth-first search (BFS) approach to explore all possible paths from the starting cell to the exit cell. It keeps track of visited cells to avoid revisiting them and ensures that the path with the minimum number of moves is found.

