def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not number:
        return '-' if from_base == 10 else ''

    if from_base < 2 or from_base > 36 or to_base < 2 or to_base > 36:
        raise ValueError("Base must be between 2 and 36")

    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    if number[0] == '-':
        negative = True
        number = number[1:]
    else:
        negative = False

    # Convert the number from the original base to decimal
    decimal_number = 0
    for digit in number:
        if digit.isdigit():
            decimal_number = decimal_number * from_base + int(digit)
        elif digit.isalpha():
            decimal_number = decimal_number * from_base + digits.index(digit.lower())
        else:
            raise ValueError(f"Invalid character '{digit}' in number")

    # Convert the decimal number to the target base
    if decimal_number == 0:
        return '-' if negative else '0'

    result = ""
    while decimal_number > 0:
        remainder = decimal_number % to_base
        result = digits[remainder] + result
        decimal_number //= to_base

    return '-' + result if negative else result
