def pack_bins(sizes: list[int], capacity: int) -> list[list[int]]:
    if not sizes:
        return []

    bins = []
    for size in sorted(sizes, reverse=True):
        if size > capacity:
            continue
        bin_index = next((i for i, bin_ in enumerate(bins) if sum(bin_) + size <= capacity), None)
