import re

def evaluate_expression(expression: str) -> float:
    # Remove all non-alphanumeric characters except for spaces and parentheses
    cleaned_expression = re.sub(r'[^0-9+\-*/\(\)\s]', '', expression)

    # Check if the cleaned expression is empty
    if not cleaned_expression:
        raise ValueError("The expression is empty.")

    # Define the precedence of operators
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '**': 3}

    # Split the expression into tokens
    tokens = re.findall(r'\d+(\.\d+)?|\b\w+\b|\(|\)', cleaned_expression)

    # Initialize the stack for operators and operands
    operator_stack = []
    operand_stack = []

    # Process each token
    for token in tokens:
        if token.isdigit():
            operand_stack.append(float(token))
        elif token.isalpha():
            operand_stack.append(token)
        elif token == '(':
            operator_stack.append(token)
        elif token == ')':
            while operator_stack[-1] != '(':
                apply_operator(operand_stack, operator_stack.pop())
            operator_stack.pop()  # Remove the '('
        else:
            while (operator_stack and operator_stack[-1] != '(' and
                   precedence[token] <= precedence[operator_stack[-1]]):
                apply_operator(operand_stack, operator_stack.pop())
            operator_stack.append(token)

    # Apply any remaining operators
    while operator_stack:
        apply_operator(operand_stack, operator_stack.pop())

    # The result should be the only element left in the operand stack
    return operand_stack[0]

def apply_operator(operand_stack, operator):
    right = operand_stack.pop()
    left = operand_stack.pop()

    if operator == '+':
        operand_stack.append(left + right)
    elif operator == '-':
        operand_stack.append(left - right)
    elif operator == '*':
        operand_stack.append(left * right)
    elif operator == '/':
        if right == 0:
            raise ValueError("Division by zero error.")
        operand_stack.append(left / right)
    elif operator == '**':
        operand_stack.append(left ** right)

# Example usage
