    print(evaluate_expression("3 + 4 * 5"))  # Output: 37.0
    print(evaluate_expression("(3 + 4) * 5"))  # Output: 35.0
    print(evaluate_expression("10 / 2"))  # Output: 5.0
    print(evaluate_expression("10 / 0"))  # Raises ValueError: Division by zero error.
except ValueError as e:
