import re

def evaluate_expression(expr: str) -> int:
    # Define the regular expression pattern for the expression
    pattern = r'(-?\d+(\.\d+)?)|(\+\-?\d+(\.\d+)?)|(\*\*/?|\/*\/?|\-\-\?|\+\+\?|\^\^?|\(|\)|[a-zA-Z]+)'

    # Split the expression into tokens using the defined pattern
    tokens = re.findall(pattern, expr)

    # Initialize variables for the current number, operator, and result
    current_number = 0
    current_operator = '+'
    result = 0

    # Iterate through the tokens
    for token in tokens:
        if token.isdigit():
            # If the token is a digit, update the current number
            current_number = float(token)
        elif token == '.':
            # If the token is a decimal point, update the current number
            current_number *= 10
        elif token == '+' or token == '-':
            # If the token is a plus or minus operator, update the current operator
            current_operator = token
        elif token == '*' or token == '/':
            # If the token is a multiplication or division operator, update the current operator
            current_operator = token
        elif token == '^':
            # If the token is an exponentiation operator, update the current operator
            current_operator = token
        elif token == '(':
            # If the token is an opening parenthesis, push the current number and operator onto the stack
            stack.append((current_number, current_operator))
            current_number = 0
            current_operator = ''
        elif token == ')':
            # If the token is a closing parenthesis, pop the last number and operator from the stack
            prev_number, prev_operator = stack.pop()
            if prev_operator == '+':
                result += prev_number + current_number
            elif prev_operator == '-':
                result += prev_number - current_number
            elif prev_operator == '*':
                result += prev_number * current_number
            elif prev_operator == '/':
                if current_number == 0:
                    raise ZeroDivisionError("Cannot divide by zero")
                result += prev_number // current_number
            elif prev_operator == '^':
                result += pow(prev_number, current_number)
            current_number = 0
            current_operator = ''

    # Add the final number to the result
    if current_operator == '+':
        result += current_number
    elif current_operator == '-':
        result -= current_number

    return int(result)
