    def tokenize(expr):
        tokens = re.findall(r'\d+|\+|-|\*|\/|^|(-?\d+)|\(|\)', expr)
        return tokens

    def parse(tokens):
        stack = []
        i = 0
        while i < len(tokens):
            token = tokens[i]
            if token.isdigit():
                num = int(token)
                while i + 1 < len(tokens) and tokens[i + 1].isdigit():
                    num = num * 10 + int(tokens[i + 1])
                    i += 1
                stack.append(num)
            elif token == '(':
                stack.append('(')
            elif token == ')':
                while stack[-1] != '(':
                    op = stack.pop()
                    b = stack.pop()
                    a = stack.pop()
                    if op == '+':
                        stack.append(a + b)
                    elif op == '-':
                        stack.append(a - b)
                    elif op == '*':
                        stack.append(a * b)
                    elif op == '/':
                        if b == 0:
                            raise ZeroDivisionError("division by zero")
                        stack.append(int(a / b))
                    elif op == '^':
                        stack.append(pow(a, b))
                stack.pop()  # Remove the '('
            elif token in ['+', '-', '*', '/', '^']:
                while (stack and stack[-1] in ['*', '/', '^'] and
                       (token == '+' or token == '-' or token == '^')):
                    op = stack.pop()
                    b = stack.pop()
                    a = stack.pop()
                    if op == '+':
                        stack.append(a + b)
                    elif op == '-':
                        stack.append(a - b)
                    elif op == '^':
                        stack.append(pow(a, b))
                stack.append(token)
            elif token == '-':
                if i > 0 and tokens[i - 1] in ['-', '+', '*', '/', '^']:
                    stack.append('-')
                else:
                    stack.append('unary_minus')
            i += 1
        while stack:
            op = stack.pop()
            b = stack.pop()
            a = stack.pop()
            if op == '+':
                stack.append(a + b)
            elif op == '-':
                stack.append(a - b)
            elif op == '*':
                stack.append(a * b)
            elif op == '/':
                if b == 0:
                    raise ZeroDivisionError("division by zero")
                stack.append(int(a / b))
            elif op == '^':
                stack.append(pow(a, b))
        return stack[0]

    tokens = tokenize(expr)
    result = parse(tokens)
    return result

