            # There's a gap before the next busy interval
            free_slots.append((current_time + min_len, start))

        current_time = max(current_time, end)

    # Check if there's a gap after the last busy interval
    if current_time < day_end - min_len:
        free_slots.append((current_time + min_len, day_end))

    return free_slots

