def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    if capacity == 0:
        return ([], [])

    cache = OrderedDict()
    results = []
    keys = []

    for op, key in operations:
        if op == 'put':
            if key in cache:
                del cache[key]
            cache[key] = None
            if len(cache) > capacity:
                cache.popitem(last=False)
        elif op == 'get':
            if key in cache:
                results.append(cache[key])
                keys.append(key)
            else:
                results.append(None)
                keys.append(key)

    return (results, keys)
