import re

def evaluate_expression(expr: str) -> int:
    # Remove spaces from the expression
    expr = expr.replace(" ", "")

    # Define the regular expression pattern for matching numbers and operators
    pattern = r"(\d+|\+|-|\*|\/|\^|\(|\))"

    # Split the expression into tokens based on the pattern
    tokens = re.findall(pattern, expr)

    # Initialize the stack for operators and operands
    stack = []
    i = 0

    while i < len(tokens):
        token = tokens[i]

        if token.isdigit():
            # If the token is a number, push it onto the stack
            stack.append(int(token))
        elif token == '(':
            # If the token is an opening parenthesis, push it onto the stack
            stack.append(token)
        elif token == ')':
            # If the token is a closing parenthesis, pop operators from the stack until an opening parenthesis is found
            while stack[-1] != '(':
                op = stack.pop()
                b = stack.pop()
                a = stack.pop()

                if op == '+':
                    stack.append(a + b)
                elif op == '-':
                    stack.append(a - b)
                elif op == '*':
                    stack.append(a * b)
                elif op == '/':
                    if b == 0:
                        raise ZeroDivisionError("Division by zero")
                    stack.append(a // b)
                elif op == '^':
                    stack.append(a ** b)

            # Pop the opening parenthesis from the stack
            stack.pop()
        elif token in "+-*/^":
            # If the token is an operator, pop two operands from the stack, apply the operator, and push the result back onto the stack
            b = stack.pop()
            a = stack.pop()

            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
