import re

def evaluate_expression(expr: str) -> int:
    # Remove spaces from the expression
    expr = expr.replace(" ", "")

    # Define the precedence of operators
    precedence = {
        '^': 3,
        '*': 2,
        '/': 2,
        '+': 1,
        '-': 1
    }

    # Define the function to apply an operator
    def apply_operator(operators, values):
        while operators and operators[-1] != '(' and precedence[operators[-1]] >= precedence[token]:
            op = operators.pop()
            b = values.pop()
            a = values.pop()
            if op == '^':
                values.append(a ** b)
            elif op == '*':
                values.append(a * b)
            elif op == '/':
                if b == 0:
                    raise ZeroDivisionError("division by zero")
                values.append(a / b)
            else:
                values.append(a - b)

    # Define the function to parse the expression
    def parse_expr():
        tokens = re.findall(r'\d+|\(|\)|[\+\-\*/\^\)]', expr)
        values = []
        operators = []
        i = 0

        while i < len(tokens):
            token = tokens[i]

            if token.isdigit():
                values.append(int(token))
            elif token == '(':
                operators.append(token)
            elif token == ')':
                while operators[-1] != '(':
                    apply_operator(operators, values)
                operators.pop()  # Remove the '('
            elif token in precedence:
                while operators and operators[-1] != '(' and precedence[operators[-1]] >= precedence[token]:
                    apply_operator(operators, values)
                operators.append(token)
            i += 1

        while operators:
            apply_operator(operators, values)

    parse_expr()
    return values[0]

# Example usage
