def boustrophedon_order(matrix: list[list[int]]) -> list[int]:
    if not matrix:
        return []

    result = []
    i, j = 0, 0
    direction = 'right'

    while True:
        result.append(matrix[i][j])

        if direction == 'right':
            if j + 1 < len(matrix[0]) and matrix[i][j + 1] != 0:
                j += 1
            else:
                direction = 'down'
        elif direction == 'down':
            if i + 1 < len(matrix) and matrix[i + 1][j] != 0:
                i += 1
            else:
                direction = 'left'
        elif direction == 'left':
            if j - 1 >= 0 and matrix[i][j - 1] != 0:
                j -= 1
            else:
                direction = 'up'
        elif direction == 'up':
            if i - 1 >= 0 and matrix[i - 1][j] != 0:
                i -= 1
            else:
                break

    return result
