def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    # Create adjacency list representation of the graph
    adj_list = defaultdict(list)
    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    # Initialize distances and parent arrays
    dist = [float('inf')] * n
    parent = [-1] * n
    dist[source] = 0

    # Priority queue to store nodes based on their distance
    pq = [(0, source)]

    while pq:
        current_dist, current_node = heapq.heappop(pq)

        if current_node == target:
            break

        for neighbor in adj_list[current_node]:
            new_dist = current_dist + 1
            if new_dist < dist[neighbor]:
                dist[neighbor] = new_dist
                parent[neighbor] = current_node
                heapq.heappush(pq, (new_dist, neighbor))

    # Check if there is a path from source to target
    if dist[target] == float('inf'):
        return 0

    # Count the number of shortest paths using backtracking
    def backtrack(node):
        if node == target:
            return 1
        count = 0
        for neighbor in adj_list[node]:
            if dist[neighbor] == dist[node] + 1:
                count += backtrack(neighbor)
        return count

    return backtrack(source)
