def min_coins_bounded(coins: list[int], limits: list[int], target: int) -> int:
    # Base case: if the target amount is 0, no coins are needed
    if target == 0:
        return 0

    # Initialize a list dp where dp[i] represents the minimum number of coins needed to make up amount i
    dp = [float('inf')] * (target + 1)

    # Fill the DP array
    for i in range(1, target + 1):
        for j in range(len(coins)):
            if i >= coins[j] and limits[j] > 0:
                dp[i] = min(dp[i], dp[i - coins[j]] + 1)

    # If dp[target] is still infinity, it means there is no way to make up the target amount with the given constraints
    if dp[target] == float('inf'):
        return -1

    # Return the result
    return dp[target]
