def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    ip = 0
    max_instructions = 1000

    while ip < len(program) and ip < max_instructions:
        instruction = program[ip]

        if instruction.startswith("PUSH"):
            _, value = instruction.split()
            stack.append(int(value))
        elif instruction == "POP":
            if stack:
                stack.pop()
            else:
                return None
        elif instruction == "DUP":
            if stack:
                stack.append(stack[-1])
            else:
                return None
        elif instruction == "SWAP":
            if len(stack) >= 2:
                stack[-1], stack[-2] = stack[-2], stack[-1]
            else:
                return None
        elif instruction in ["ADD", "SUB", "MUL"]:
            if len(stack) >= 2:
                b, a = stack.pop(), stack.pop()
                if instruction == "ADD":
                    stack.append(a + b)
                elif instruction == "SUB":
                    stack.append(a - b)
                elif instruction == "MUL":
                    stack.append(a * b)
            else:
                return None
        elif instruction == "JMP":
            _, target_index = instruction.split()
            ip = int(target_index)
        elif instruction == "JZ":
            _, target_index = instruction.split()
            if stack and stack[-1] == 0:
                ip = int(target_index)
            else:
                ip += 1
        else:
            return None

        ip += 1

    return stack if not stack else None
