def decimal_to_binary(n: int) -> str:
    if n == 0:
        return '0'

    binary_digits = []
    while n > 0:
        binary_digits.append(str(n % 2))
        n //= 2

    # Reverse the list to get the correct binary representation
    binary_digits.reverse()

    # Remove the '0b' prefix if present
    if binary_digits[0] == '0':
        binary_digits.pop(0)

    # Join the binary digits into a single string
    return ''.join(binary_digits)
