from math import gcd

def lcm(a, b):
    return abs(a*b) // gcd(a, b)

def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    # Extract the moduli and remainders from the congruences
    moduli = [m for r, m in congruences]
    remainders = [r for r, m in congruences]

    # Calculate the product of all moduli
    product_of_moduli = 1
    for m in moduli:
        product_of_moduli *= m

    # Calculate the partial products for each remainder
    partial_products = []
    for r in remainders:
        partial_product = product_of_moduli // m
        partial_products.append(partial_product)

    # Calculate the inverse of each partial product modulo its corresponding modulus
    inverses = []
    for p, m in zip(partial_products, moduli):
        inverse = pow(p, -1, m)
        inverses.append(inverse)

    # Calculate the solution using the Chinese Remainder Theorem
    x = sum(r * p * inverse for r, p, inverse in zip(remainders, partial_products, inverses))
    x %= product_of_moduli

    # Check if the solution satisfies all the original congruences
    for r, m in congruences:
        if x % m != r:
            return None

    return (x, product_of_moduli)
