    moduli = [m for r, m in congruences]

    # Calculate the product of all moduli
    product_moduli = 1
    for m in moduli:
        product_moduli *= m

    # Initialize the solution variables
    x = 0
    L = product_moduli

    # Iterate through each congruence
    for r, m in congruences:
        # Calculate the modular inverse of r modulo m
        inv_r = pow(r, -1, m)

        # Update the solution variables
        x = (x + r * inv_r * product_moduli % L) % L
        L = lcm(L, m)

    return (x, L)
