from collections import defaultdict

def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = defaultdict(int)
    waiting_orders = defaultdict(list)

    for kind, item, quantity in events:
        if kind == 'receive':
            stock[item] += quantity
        elif kind == 'order':
            if item in stock:
                stock[item] -= quantity
                if stock[item] < 0:
                    waiting_orders[item].append((item, -stock[item]))
                    stock[item] = 0
            else:
                waiting_orders[item].append((item, quantity))

    return dict(stock), list(waiting_orders.items())
