        elif kind == 'order':
            if item in waiting_orders:
                waiting_orders[item].append((quantity, stock[item]))
                stock[item] -= quantity
            else:
                stock[item] -= quantity
                if stock[item] < 0:
                    waiting_orders[item].append((-stock[item], stock[item]))

    final_stock = dict(stock)
    waiting_orders_list = [tuple(order) for order in waiting_orders.values()]

    return final_stock, waiting_orders_list

