def run_stack_machine(program: list[str]) -> list[int]:
    if len(program) > 1000:
        raise RuntimeError("Program too long")

    stack = []
    i = 0

    while i < len(program):
        instruction = program[i]

        if instruction.startswith("PUSH"):
            try:
                value = int(instruction.split()[1])
                stack.append(value)
            except ValueError:
                raise ValueError(f"Invalid PUSH instruction: {instruction}")

        elif instruction == "POP":
            if not stack:
                raise ValueError("Attempted to POP from empty stack")
            stack.pop()

        elif instruction == "DUP":
            if not stack:
                raise ValueError("Attempted to DUP from empty stack")
            stack.append(stack[-1])

        elif instruction == "SWAP":
            if len(stack) < 2:
                raise ValueError("Not enough elements to swap")
            stack[-1], stack[-2] = stack[-2], stack[-1]

        elif instruction in ["ADD", "SUB", "MUL"]:
            if len(stack) < 2:
                raise ValueError("Not enough elements to perform operation")
            right = stack.pop()
            left = stack.pop()
            if instruction == "ADD":
                stack.append(left + right)
            elif instruction == "SUB":
                stack.append(left - right)
            else:
                stack.append(left * right)

        elif instruction == "JMP":
            try:
                target = int(instruction.split()[1])
                if target >= len(program):
                    raise IndexError("Jump out of bounds")
                i = target
            except ValueError:
                raise ValueError(f"Invalid JMP instruction: {instruction}")

        elif instruction == "JZ":
            try:
                target = int(instruction.split()[1])
                if stack[-1] == 0:
                    i = target
                else:
                    i += 1
            except ValueError:
                raise ValueError(f"Invalid JZ instruction: {instruction}")

        elif instruction == "HALT":
            break

        else:
            raise ValueError(f"Unknown instruction: {instruction}")

    return stack
