def run_bank_ops(balances: dict[str, int], ops: list[tuple]) -> tuple[dict[str, int], list[int]]:
    # Ensure all accounts start unfrozen
    for account in balances:
        balances[account] = max(0, balances[account])

    failed_indices = []
    for i, op in enumerate(ops):
        action, account, amount = op

        if action == 'deposit':
            if account in balances and amount > 0:
                balances[account] += amount
            else:
                failed_indices.append(i)

        elif action == 'withdraw':
            if account in balances and amount > 0 and balances[account] >= amount:
                balances[account] -= amount
            else:
                failed_indices.append(i)

        elif action == 'transfer':
            if account in balances and recipient in balances and amount > 0 and balances[account] >= amount:
                balances[recipient] += amount - 2
                balances[account] -= amount
            else:
                failed_indices.append(i)

        elif action == 'freeze':
            if account in balances:
                balances[account] = 0
            else:
                failed_indices.append(i)

        elif action == 'unfreeze':
            if account in balances:
                balances[account] = max(0, balances[account])
            else:
                failed_indices.append(i)

    return balances, failed_indices
