def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    ip = 0

    while ip < len(program):
        instruction = program[ip]

        if instruction.startswith('PUSH'):
            try:
                value = int(instruction[4:])
                stack.append(value)
            except ValueError:
                raise ValueError("Invalid PUSH instruction")

        elif instruction == 'POP':
            if not stack:
                raise ValueError("Stack underflow")
            stack.pop()

        elif instruction == 'DUP':
            if not stack:
                raise ValueError("Stack underflow")
            stack.append(stack[-1])

        elif instruction == 'SWAP':
            if len(stack) < 2:
                raise ValueError("Not enough elements for SWAP")
            stack[-1], stack[-2] = stack[-2], stack[-1]

        elif instruction.startswith('ADD'):
            if len(stack) < 2:
                raise ValueError("Not enough elements for ADD")
            stack[-2] += stack[-1]
            stack.pop()

        elif instruction.startswith('SUB'):
            if len(stack) < 2:
                raise ValueError("Not enough elements for SUB")
            stack[-2] -= stack[-1]
            stack.pop()

        elif instruction.startswith('MUL'):
            if len(stack) < 2:
                raise ValueError("Not enough elements for MUL")
            stack[-2] *= stack[-1]
            stack.pop()

        elif instruction.startswith('JMP'):
            try:
                target = int(instruction[3:])
                if target >= len(program) or target < 0:
                    raise ValueError("Invalid jump target")
                ip = target - 1
            except ValueError:
                raise ValueError("Invalid JMP instruction")

        elif instruction.startswith('JZ'):
            try:
                target = int(instruction[3:])
                if target >= len(program) or target < 0:
                    raise ValueError("Invalid jump target")
                if stack[-1] == 0:
                    ip = target - 1
            except ValueError:
                raise ValueError("Invalid JZ instruction")

        elif instruction == 'HALT':
            break

        else:
            raise ValueError(f"Unknown instruction: {instruction}")

        ip += 1

    return stack
