    stack = []
    for i, instruction in enumerate(program):
        parts = instruction.split()
        if parts[0] == 'PUSH':
            stack.append(int(parts[1]))
        elif parts[0] == 'POP':
            if stack:
                stack.pop()
            else:
                return None
        elif parts[0] == 'DUP':
            if stack:
                stack.append(stack[-1])
            else:
                return None
        elif parts[0] == 'SWAP':
            if len(stack) >= 2:
                stack[-1], stack[-2] = stack[-2], stack[-1]
            else:
