def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    waiting = []

    for event_type, item, quantity in events:
        if event_type == 'receive':
            if item not in stock:
                stock[item] = 0
            stock[item] += quantity
        elif event_type == 'order':
            if item in stock:
                stock[item] -= quantity
                if stock[item] < 0:
                    waiting.append((item, quantity))
            else:
                waiting.append((item, quantity))

    waiting.sort(key=lambda x: x[0])
    return stock, waiting
