def matrix_power_mod(matrix: list[list[int]], exp: int, mod: int) -> list[list[int]]:
    def matrix_multiply(a: list[list[int]], b: list[list[int]]) -> list[list[int]]:
        result = [[0 for _ in range(len(b[0]))] for _ in range(len(a))]
        for i in range(len(a)):
            for j in range(len(b[0])):
                for k in range(len(b)):
                    result[i][j] += (a[i][k] * b[k][j]) % mod
        return result

    def matrix_square(matrix: list[list[int]]) -> list[list[int]]:
        return matrix_multiply(matrix, matrix)

    if exp == 0:
        return [[1 if i == j else 0 for j in range(len(matrix))] for i in range(len(matrix))]
    elif exp == 1:
        return matrix
    elif exp % 2 == 0:
        half_exp = exp // 2
        squared_matrix = matrix_square(matrix)
        return matrix_multiply(squared_matrix, squared_matrix)
    else:
        return matrix_multiply(matrix, matrix_power_mod(matrix, exp - 1, mod))
